insert into public.artisans(id,name,craft_specialty,bio,location,is_verified) values
('11111111-1111-4111-8111-111111111111','Aisyah Rahman','Songket','Third-generation Songket weaver.','Kuala Terengganu',true),('22222222-2222-4222-8222-222222222222','Hassan Ismail','Ukiran','Traditional woodcarver.','Kota Bharu',true),('33333333-3333-4333-8333-333333333333','Siti Mariam','Canting','Batik artist.','Kuantan',true),('44444444-4444-4444-8444-444444444444','Rahim Salleh','Labu Sayong','Perak potter.','Kuala Kangsar',true),('55555555-5555-4555-8555-555555555555','Noraini Yusof','Anyaman','Pandan weaving specialist.','Kuching',true) on conflict(id) do nothing;
insert into public.craft_items(artisan_id,name,description,price_myr,is_local_pickup_only,is_published) select v.a::uuid,v.n,v.d,v.p,v.l,true from (values ('11111111-1111-4111-8111-111111111111','Songket Pucuk Rebung','Handwoven silk textile.',680.00,false),('11111111-1111-4111-8111-111111111111','Songket Gold Border','Formal Songket border panel.',420.00,false),('22222222-2222-4222-8222-222222222222','Ukiran Floral Panel','Carved hardwood panel.',950.00,true),('22222222-2222-4222-8222-222222222222','Miniature Ukiran Relief','Small carved relief.',180.00,false),('33333333-3333-4333-8333-333333333333','Canting Silk Scarf','Hand-painted silk scarf.',160.00,false),('33333333-3333-4333-8333-333333333333','Canting Wall Textile','Large-format batik textile.',520.00,false),('44444444-4444-4444-8444-444444444444','Labu Sayong Classic','Traditional black clay vessel.',240.00,true),('44444444-4444-4444-8444-444444444444','Labu Sayong Pair','Matched pair of vessels.',460.00,true),('55555555-5555-4555-8555-555555555555','Anyaman Market Basket','Pandan basket.',95.00,false),('55555555-5555-4555-8555-555555555555','Anyaman Storage Trunk','Lidded woven trunk.',310.00,true))v(a,n,d,p,l) where not exists(select 1 from public.craft_items c where c.name=v.n);
insert into public.workshops(artisan_id,title,description,starts_at,ends_at,capacity,price_myr,is_published) select v.a::uuid,v.t,v.d,v.s::timestamptz,v.e::timestamptz,v.c,v.p,true from (values ('11111111-1111-4111-8111-111111111111','Songket fundamentals','Learn weaving rhythm.','2026-11-07 10:00:00+08','2026-11-07 13:00:00+08',8,180.00),('33333333-3333-4333-8333-333333333333','Canting introduction','Practice wax control.','2026-11-14 10:00:00+08','2026-11-14 13:00:00+08',10,150.00),('44444444-4444-4444-8444-444444444444','Labu Sayong on the wheel','Shape a small vessel.','2026-11-21 09:00:00+08','2026-11-21 13:00:00+08',6,220.00))v(a,t,d,s,e,c,p) where not exists(select 1 from public.workshops w where w.title=v.t);
